```python
import time
import os

class SessionManager:

    def __init__(self, session_file):
        self.session_file = session_file
        self.sessions = {}

    def start_session(self):
        self.sessions[self.get_session_id()] = time.time()

    def get_session_id(self):
        if not self.sessions:
            return str(os.getpid())
        else:
            return max(self.sessions.keys())

    def active(self):
        return time.time() - self.sessions[self.get_session_id()] < 900

    def renew_session(self):
        self.sessions[self.get_session_id()] = time.time()

    def expire_session(self):
        expiration_time = time.time() + 900
        self.sessions = {key: value for key, value in self.sessions.items() if value < expiration_time}

session_manager = SessionManager("operator_session.txt")
session_manager.start_session()
while True:
    time.sleep(10)
    if session_manager.active():
        session_manager.renew_session()
    else:
        session_manager.expire_session()
```

